base.infra/app/main.tf:
terraform {
  backend "s3" {}
}
variable "prefix" {
  type = string
}
variable "env" {
  type = string
}
variable "timeout" {
  type    = number
  default = 30
}
resource "aws_sqs_queue" "q" {
  name                       = "${var.prefix}-${var.env}"
  visibility_timeout_seconds = var.timeout
}

